/**
 * PSE Financial History Provider
 *
 * Reads data/pse-financial-history.json (generated by
 * scripts/scrape-pse-financial-history.ts, a separate monthly pipeline —
 * see .github/workflows/pse-financial-history-monthly.yml) which scrapes a
 * real multi-quarter financial series per PSE company from PSE Edge
 * quarterly filings.
 *
 * When a symbol has a real series here, the Financials chart can render it
 * instead of the synthetic market-cap/sector-median model, and StockPage
 * can drop its "estimated" disclaimer for that symbol. A symbol with no
 * real series returns null — callers fall back to the honest synthetic
 * model (and keep the disclaimer), never a fabricated value.
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

export interface PseFinancialHistoryPoint {
  period: string;
  asOfPeriod: string | null;
  revenue: number | null;
  netIncome: number | null;
  totalAssets: number | null;
  totalEquity: number | null;
  totalLiabilities: number | null;
  eps: number | null;
  sourceUrl: string;
}

export interface PseFinancialHistoryRecord {
  symbol: string;
  series: PseFinancialHistoryPoint[];
}

type HistoryMap = Record<string, PseFinancialHistoryRecord | { error: string }>;

let historyCache: HistoryMap | null = null;

function loadHistoryMap(): HistoryMap {
  if (historyCache !== null) return historyCache;
  let loaded: HistoryMap = {};
  try {
    const raw = readFileSync(resolve(process.cwd(), 'data/pse-financial-history.json'), 'utf-8');
    loaded = JSON.parse(raw).results ?? {};
  } catch {
    // File not generated yet (monthly pipeline hasn't run) — no real data.
  }
  historyCache = loaded;
  return loaded;
}

/** Real multi-quarter financial series for a symbol, or null if none is
 * available. Never fabricated — callers should fall back to the synthetic
 * model (with its honest "estimated" disclaimer) rather than guessing. */
export function loadPseFinancialHistory(symbol: string): PseFinancialHistoryRecord | null {
  const record = loadHistoryMap()[symbol.toUpperCase()];
  if (!record || 'error' in record) return null;
  if (!record.series || record.series.length < 2) return null;
  return record;
}

/** Number of real quarters available for a symbol (0 if none). */
export function realFinancialQuarterCount(symbol: string): number {
  const record = loadHistoryMap()[symbol.toUpperCase()];
  if (!record || 'error' in record) return 0;
  return record.series.length;
}
